<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { supabase } from '@/lib/supabase'
const rows=ref<any[]>([]),error=ref(''),busy=ref(false),loading=ref(true),selected=ref<any>(null),historyId=ref<string|null>(null)
const amount=ref(0),method=ref('cash'),note=ref(''),reference=ref('')
const latestPayments=computed(()=>rows.value.flatMap(r=>(r.supplier_payments??[]).map((p:any)=>({...p,supplierName:r.suppliers?.name??'Supplier'}))).sort((a,b)=>new Date(b.payment_date).getTime()-new Date(a.payment_date).getTime()).slice(0,50))
async function load(){loading.value=true;error.value='';const {data,error:e}=await supabase.from('supplier_credits').select('id,purchase_id,supplier_id,original_amount,amount_paid,balance,due_date,status,notes,created_at,suppliers(name,phone),purchases(purchase_number),supplier_payments(id,receipt_number,amount,payment_method,payment_date,reference_number,notes)').order('created_at',{ascending:false});if(e)error.value=e.message;else rows.value=data??[];loading.value=false}
async function pay(){if(!selected.value)return;busy.value=true;error.value='';try{const {error:e}=await supabase.rpc('record_creditor_payment',{p_supplier_credit_id:selected.value.id,p_receipt_number:'SUP-'+Date.now(),p_amount:Number(amount.value),p_payment_method:method.value,p_reference_number:reference.value||null,p_notes:note.value||null});if(e)throw e;selected.value=null;amount.value=0;note.value='';reference.value='';await load()}catch(e:any){error.value=e.message??'Could not record supplier payment'}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="page-wrap"><div class="page-heading"><div><h1>Supplier creditors</h1><p>Outstanding supplier balances and repayments linked to purchase records.</p></div><button class="btn" @click="load">Refresh</button></div><p v-if="error" class="alert">{{error}}</p><p v-if="loading" class="empty">Loading supplier balances…</p>
<div v-else class="table-scroll"><table><thead><tr><th>Supplier</th><th>Purchase</th><th>Original amount</th><th>Paid</th><th>Balance</th><th>Status</th><th>Date</th><th>Actions</th></tr></thead><tbody><template v-for="row in rows" :key="row.id"><tr><td>{{row.suppliers?.name??'—'}}<small>{{row.suppliers?.phone??''}}</small></td><td>{{row.purchases?.purchase_number??'—'}}</td><td>UGX {{Number(row.original_amount).toLocaleString()}}</td><td>UGX {{Number(row.amount_paid).toLocaleString()}}</td><td>UGX {{Number(row.balance).toLocaleString()}}</td><td>{{row.status}}</td><td>{{new Date(row.created_at).toLocaleDateString()}}</td><td class="actions"><button class="link" @click="historyId=historyId===row.id?null:row.id">History</button><button v-if="Number(row.balance)>0" class="link" @click="selected=row;amount=Number(row.balance)">Record payment</button></td></tr>
<tr v-if="historyId===row.id"><td colspan="8"><div v-if="row.supplier_payments?.length" class="table-scroll"><table><thead><tr><th>Receipt</th><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th><th>Notes</th></tr></thead><tbody><tr v-for="p in row.supplier_payments" :key="p.id"><td>{{p.receipt_number}}</td><td>{{new Date(p.payment_date).toLocaleString()}}</td><td>UGX {{Number(p.amount).toLocaleString()}}</td><td>{{p.payment_method}}</td><td>{{p.reference_number??'—'}}</td><td>{{p.notes??'—'}}</td></tr></tbody></table></div><p v-else class="empty">No repayments recorded.</p></td></tr></template><tr v-if="!rows.length"><td colspan="8" class="empty">No supplier credit records found.</td></tr></tbody></table></div>
<div class="panel mt"><h2>Latest supplier repayments</h2><div class="table-scroll"><table><thead><tr><th>Supplier</th><th>Receipt</th><th>Date</th><th>Amount</th><th>Method</th></tr></thead><tbody><tr v-for="p in latestPayments" :key="p.id"><td>{{p.supplierName}}</td><td>{{p.receipt_number}}</td><td>{{new Date(p.payment_date).toLocaleString()}}</td><td>UGX {{Number(p.amount).toLocaleString()}}</td><td>{{p.payment_method}}</td></tr><tr v-if="!latestPayments.length"><td colspan="5" class="empty">No supplier repayments yet.</td></tr></tbody></table></div></div>
<div v-if="selected" class="modal-backdrop" @click.self="selected=null"><form class="modal" @submit.prevent="pay"><h2>Record supplier payment</h2><p>{{selected.suppliers?.name}} · Balance UGX {{Number(selected.balance).toLocaleString()}}</p><label>Amount<input v-model.number="amount" type="number" min="0.01" :max="selected.balance" step="0.01" class="control" required></label><label>Method<select v-model="method" class="control"><option value="cash">Cash</option><option value="bank">Bank</option><option value="mobile_money">Mobile money</option></select></label><label>Reference<input v-model="reference" class="control"></label><label>Notes<input v-model="note" class="control"></label><div class="modal-actions"><button type="button" class="btn" @click="selected=null">Cancel</button><button class="btn primary" :disabled="busy||amount<=0||amount>selected.balance">{{busy?'Saving…':'Save payment'}}</button></div></form></div>
</section></template>